 e['plot_vi']=' '.join([e['scenes'][0]['narration'].split('"')[0],e['scenes'][2]['narration'],e['scenes'][-1]['narration'].split('"')[-1]]);e['opening_function_vi']=e['scenes'][0]['narration'].split('.')[0]+'.'
 e['scenes'][3]['practice_pause_seconds']=4
